const resp = $('Get Chat History').first().json || {};
const items = resp.data || [];
// Drop the most recent message — it's the one we just received and the agent
// already gets it via 'chatInput' in the prompt.
const prior = items.slice(0, Math.max(0, items.length - 1));
const transcript = prior
  .map(m => `${m.role === 'user' ? 'User' : 'Assistant'}: ${m.text}`)
  .join('\n');
return [{ json: { transcript, totalMessages: items.length } }];
